function isGenerating(): boolean {
  const tavern = SillyTavern as typeof SillyTavern & {
    isGenerating?: boolean;
    getContext?: () => { isGenerating?: boolean };
  };
  return Boolean(tavern.isGenerating || tavern.getContext?.()?.isGenerating);
}

function readLatestState(): { messageId: number; mvuData: Mvu.MvuData; statData: StatData } {
  const messageId = getLastMessageId();
  if (messageId < 0) {
    throw new Error('当前聊天中没有可写入变量的消息');
  }

  const target = klona(Mvu.getMvuData({ type: 'message', message_id: messageId }));
  let raw = _.get(target, 'stat_data');
  if (_.isEmpty(raw)) {
    for (let depth = -2; depth >= -100; depth--) {
      try {
        const previous = Mvu.getMvuData({ type: 'message', message_id: depth });
        const previousStatData = _.get(previous, 'stat_data');
        if (!_.isEmpty(previousStatData)) {
          raw = previousStatData;
          break;
        }
      } catch {
        break;
      }
    }
  }

  return { messageId, mvuData: target, statData: Schema.parse(raw) };
}

async function writeLatestState(messageId: number, mvuData: Mvu.MvuData, statData: StatData): Promise<void> {
  const parsedStatData = Schema.parse(statData);
  const target = { type: 'message', message_id: messageId } as const;
  _.set(mvuData, 'stat_data', parsedStatData);
  try {
    await Mvu.replaceMvuData(mvuData, target);
  } catch (error) {
    console.warn('[世界快穿模拟器] MVU 写入接口失败，继续使用底层变量接口保存前端操作', error);
  }
  updateVariablesWith(variables => {
    const next = klona(variables);
    _.set(next, 'stat_data', parsedStatData);
    return next;
  }, target);
  const saved = Schema.safeParse(_.get(getVariables(target), 'stat_data'));
  if (!saved.success || !_.isEqual(saved.data, parsedStatData)) {
    throw new Error('前端变量写入后校验失败，操作已停止');
  }
}

let stateMutationQueue: Promise<void> = Promise.resolve();

function enqueueStateMutation<T>(operation: () => Promise<T>): Promise<T> {
  const result = stateMutationQueue.then(operation, operation);
  stateMutationQueue = result.then(
    () => undefined,
    () => undefined,
  );
  return result;
}

let rewardSettlementBusy = false;

async function settlePendingRewardsUnsafe(): Promise<string[]> {
  if (rewardSettlementBusy) return [];
  rewardSettlementBusy = true;

  try {
    const { messageId, mvuData, statData } = readLatestState();
    const next = klona(statData);
    const messages: string[] = [];
    let changed = false;
    const task = next.当前世界.当前任务;

    if (task.状态 === '已完成' && !task.$奖励已结算) {
      const energyBefore = next.穿梭仪.能量;
      next.主角.世界币 += task.世界币奖励;
      next.穿梭仪.能量 = _.clamp(next.穿梭仪.能量 + task.能量奖励, 0, 100);
      task.$奖励已结算 = true;
      changed = true;
      messages.push(`任务奖励已结算：◈ ${task.世界币奖励}，能量 +${next.穿梭仪.能量 - energyBefore}`);
    }

    const anomaly = next.当前世界.异常事件;
    if (anomaly && !anomaly.$奖励已结算 && (anomaly.状态 === '已解决' || anomaly.状态 === '已失控')) {
      if (anomaly.状态 === '已解决') {
        const energyBefore = next.穿梭仪.能量;
        const stabilityBefore = next.当前世界.稳定度;
        next.主角.世界币 += anomaly.奖励.世界币;
        next.穿梭仪.能量 = _.clamp(next.穿梭仪.能量 + anomaly.奖励.能量, 0, 100);
        next.当前世界.稳定度 = _.clamp(next.当前世界.稳定度 + anomaly.奖励.稳定度, 0, 100);
        messages.push(
          `异常事件奖励已结算：◈ ${anomaly.奖励.世界币}，能量 +${next.穿梭仪.能量 - energyBefore}，稳定度 +${next.当前世界.稳定度 - stabilityBefore}`,
        );
      }
      anomaly.$奖励已结算 = true;
      changed = true;
    }

    if (changed) await writeLatestState(messageId, mvuData, next);
    return messages;
  } finally {
    rewardSettlementBusy = false;
  }
}

async function purchaseProductUnsafe(productName: string): Promise<string> {
  if (isGenerating()) {
    throw new Error('AI生成期间不能购买商品');
  }

  const { messageId, mvuData, statData } = readLatestState();
  const next = klona(statData);
  const product = next.世界商店.商品[productName];
  if (!product) {
    throw new Error('商品已经售罄或不存在');
  }
  if (product.库存 <= 0) {
    throw new Error('商品库存不足');
  }
  if (next.主角.世界币 < product.价格) {
    throw new Error(`世界币不足，还需要 ${product.价格 - next.主角.世界币}`);
  }

  if (product.商品类型 === '技能') {
    const owned = next.主角.技能[productName];
    if (owned?.持久性 === '永久') {
      throw new Error('已经拥有这个永久技能');
    }
    next.主角.技能[productName] = {
      类型: product.类型,
      描述: product.描述,
      持久性: product.持久性,
      来源: '世界商店',
    };
  } else {
    const owned = next.主角.物品[productName];
    if (owned) {
      owned.数量 += 1;
    } else {
      next.主角.物品[productName] = {
        类型: product.类型,
        描述: product.描述,
        数量: 1,
        持久性: product.持久性,
        来源: '世界商店',
      };
    }
  }

  next.主角.世界币 -= product.价格;
  product.库存 -= 1;
  if (product.库存 <= 0) {
    delete next.世界商店.商品[productName];
  }

  await writeLatestState(messageId, mvuData, next);
  return `已购买「${productName}」，花费 ${product.价格} 世界币`;
}

async function upgradeShuttleModuleUnsafe(moduleName: ShuttleModuleName): Promise<string> {
  if (isGenerating()) {
    throw new Error('AI生成期间不能升级穿梭仪模块');
  }

  const { messageId, mvuData, statData } = readLatestState();
  const next = klona(statData);
  const currentLevel = next.穿梭仪.$模块[moduleName];
  const cost = SHUTTLE_MODULE_CONFIG[moduleName].costs[currentLevel];
  if (cost === undefined) {
    throw new Error('该模块已经达到最高等级');
  }
  if (next.主角.世界币 < cost) {
    throw new Error(`世界币不足，还需要 ${cost - next.主角.世界币}`);
  }

  next.主角.世界币 -= cost;
  next.穿梭仪.$模块[moduleName] = currentLevel + 1;
  next.$穿梭仪模块[moduleName] = currentLevel + 1;
  await writeLatestState(messageId, mvuData, next);
  return `「${moduleName}」已升级至 ${currentLevel + 1} 级，花费 ${cost} 世界币`;
}

async function setCharacterTrackedUnsafe(characterName: string, tracked: boolean): Promise<string> {
  if (isGenerating()) {
    throw new Error('AI生成期间不能修改角色追踪状态');
  }

  const { messageId, mvuData, statData } = readLatestState();
  const next = klona(statData);
  const character = next.当前角色[characterName];
  if (!character) {
    throw new Error('角色已经不存在');
  }

  if (tracked && character.所属世界 === '未记录') {
    character.所属世界 = next.当前世界.名称;
  }
  character.$追踪 = tracked;

  const originWorld = character.所属世界;
  const characterId = `${originWorld}::${characterName}`;
  if (tracked) {
    next.$追踪角色[characterId] = { 角色名: characterName, 所属世界: originWorld };
  } else {
    delete next.$追踪角色[characterId];
    const historyRecord = next.穿越记录[originWorld];
    if (historyRecord) delete historyRecord.追踪角色[characterName];
    if (originWorld !== next.当前世界.名称) delete next.当前角色[characterName];
  }

  await writeLatestState(messageId, mvuData, next);
  return tracked
    ? `已追踪「${characterName}」，离开其所属世界后仍会保留并更新档案`
    : originWorld === next.当前世界.名称
      ? `已取消追踪「${characterName}」，离开当前世界时将不再保留档案`
      : `已取消追踪「${characterName}」，其离屏档案已移除`;
}

async function deleteCharacterUnsafe(characterName: string): Promise<string> {
  if (isGenerating()) {
    throw new Error('AI生成期间不能删除角色');
  }

  const { messageId, mvuData, statData } = readLatestState();
  const next = klona(statData);
  const character = next.当前角色[characterName];
  if (!character) {
    throw new Error('角色已经不存在');
  }

  const originWorld = character.所属世界 === '未记录' ? next.当前世界.名称 : character.所属世界;
  const historyRecord = next.穿越记录[originWorld];
  if (historyRecord) delete historyRecord.追踪角色[characterName];
  delete next.$追踪角色[`${originWorld}::${characterName}`];
  delete next.当前角色[characterName];
  next.$已删除角色[`${originWorld}::${characterName}`] = {
    角色名: characterName,
    所属世界: originWorld,
    删除于: `${next.当前世界.名称} · ${next.当前世界.当前时间}`,
  };

  await writeLatestState(messageId, mvuData, next);
  return `已永久删除「${characterName}」，后续不会再生成该角色内容`;
}

export function settlePendingRewards(): Promise<string[]> {
  return enqueueStateMutation(settlePendingRewardsUnsafe);
}

export function purchaseProduct(productName: string): Promise<string> {
  return enqueueStateMutation(() => purchaseProductUnsafe(productName));
}

export function upgradeShuttleModule(moduleName: ShuttleModuleName): Promise<string> {
  return enqueueStateMutation(() => upgradeShuttleModuleUnsafe(moduleName));
}

export function setCharacterTracked(characterName: string, tracked: boolean): Promise<string> {
  return enqueueStateMutation(() => setCharacterTrackedUnsafe(characterName, tracked));
}

export function deleteCharacter(characterName: string): Promise<string> {
  return enqueueStateMutation(() => deleteCharacterUnsafe(characterName));
}
